 *  picker handle it identically). Also writes the underscore-named
 *  `roster_context.json` so persistArtifacts records a stage-aligned
 *  entry alongside the canonical hyphenated artifact. */
async function writeRosterContextArtifact(
  runDir: string,
  runId: string,
  artifact: RosterContextArtifact,
  log: Logger,
): Promise<void> {
  try {
    const artifactsDir = join(runDir, 'artifacts');
    mkdirSync(artifactsDir, { recursive: true });
    const envelope = JSON.stringify({
      runId,
      stepName: 'roster_context',
      artifact,
      writtenAt: new Date().toISOString(),
    });
    await writeFile(join(artifactsDir, `${ROSTER_CONTEXT_ARTIFACT_NAME}.json`), envelope);
    await writeFile(join(artifactsDir, 'roster_context.json'), envelope);
  } catch (err) {
    log.warn('roster_context.write',
      `roster-context.json write failed: ${err instanceof Error ? err.message : String(err)}`);
  }
}

