/**
 * Ingest step (ADR-0022).
 *
 * Pure data step. Loads articles from the **Feed source adapter** for the
 * requested date range, applies freshness ordering, and applies the
 * `articleLimit` cap. Emits `ingest.json` carrying raw FeedArticles WITH
 * body — this is the only step in the pipeline whose artifact carries
 * full body text. Downstream steps consume the body-stripped chunk
 * artifact instead.
 *
 * No LLM. No lint retry. The step is deterministic given (date range,
 * feed source, articleLimit).
 */

import type { Logger } from 'shared/logger.js';
import type { FeedArticle, FeedSource, FeedSourceQuery } from '../../../services/articles/index.js';

export interface IngestInput {
  from:           string;
  to:             string;
  feedSource:     FeedSource;
  sourceLabel:    string;
  articleLimit?:  number;
}

export interface IngestArtifact {
  source_label:  string;
  from:          string;
  to:            string;
  raw_count:     number;
  articles:      FeedArticle[];
}

export async function runIngestStep(input: IngestInput, log: Logger): Promise<IngestArtifact> {
  const t0 = performance.now();
  log.info('ingest.start', `Ingest: pulling ${input.from} → ${input.to} via ${input.sourceLabel}`);
  const hasArticleLimit = Number.isSafeInteger(input.articleLimit) && input.articleLimit !== undefined && input.articleLimit > 0;

  const query: FeedSourceQuery = {
    from: input.from,
    to:   input.to,
  };
  const rawArticles = await input.feedSource.loadArticles(query, log);

  // ADR-0021: deterministic importance scoring is gone. Every article goes
