 *  these files on its own. `services/feed/trace.ts`'s `FeedTraceRecorder.flush()`
 *  calls this directly, and `persistArtifacts` (index.ts) calls it again when
 *  it rebuilds the run's manifest from scratch at the end, so the final
 *  manifest is complete regardless of what ran mid-run. Existing entries are
 *  never clobbered (same defensive rule as `addSidecarFilesToManifest`). */
export function addFeedCallFilesToManifest(runDir: string, manifest: ArtifactManifest): void {
  const dir = join(runDir, 'artifacts', 'feed-calls');
  if (!existsSync(dir)) return;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isFile() || !entry.name.endsWith('.json')) continue;
    const key = `feed-calls/${entry.name.slice(0, -'.json'.length)}`;
    if (manifest.artifacts[key]) continue;
    const relPath = `artifacts/feed-calls/${entry.name}`;
    const fullPath = join(runDir, relPath);
    const buf = readFileSync(fullPath);
    manifest.artifacts[key] = {
      step:       key,
      path:       relPath,
      sha256:     sha256Hex(buf),
      byte_size:  buf.byteLength,
      written_at: new Date().toISOString(),
    };
  }
}

