/** Atomically write a JSON file via .tmp + rename, returning the bytes
 *  written and sha256. The directory is created if it doesn't exist. */
export function writeJsonAtomic(filePath: string, value: unknown): { sha256: string; byte_size: number } {
  mkdirSync(dirname(filePath), { recursive: true });
  const payload = JSON.stringify(value, null, 2);
  const buf = Buffer.from(payload, 'utf-8');
  const tmpPath = `${filePath}.tmp`;
  writeFileSync(tmpPath, buf);
  renameSync(tmpPath, filePath);
  return { sha256: sha256Hex(buf), byte_size: buf.byteLength };
}

